    <main id="contenido" class="ask" data-chat>
      <div class="ask__glow" aria-hidden="true"></div>

      <div class="ask__inner shell">
        <!-- Rastro de lo ya respondido: también es la forma de volver atrás. -->
        <div class="ask__top">
          <div class="ask__trail" data-ask-trail data-empty="true" aria-label="Respuestas"></div>
          <p class="ask__count"><span data-ask-count>1</span></p>
        </div>
        <div
          class="ask__bar"
          data-ask-bar
          role="progressbar"
          aria-label="Avance"
          aria-valuemin="0"
          aria-valuemax="100"
          aria-valuenow="0"
        ></div>

        <!-- Sin aria-live: cada paso reemplaza el panel entero y el lector
             repetiría pregunta y todas las opciones. El foco viaja al título
             del paso nuevo, que es lo que hay que oír. -->
        <div class="ask__stage" data-ask-stage></div>

        <!-- Salida directa, disponible en todos los pasos. -->
        <p class="ask__direct">
          ¿Prefieres hablar con alguien?
          <button type="button" data-ask-direct>Ver las líneas directas</button>
        </p>
      </div>
    </main>

